import type { Cancer, Cited, DrugClass, OncDrug, OncSource } from '../types.js';

// Targeted and related drugs for hematologic cancers, from the FDA labels read in full on DailyMed (SPL effective dates in SOURCES below).
// Every statement is paraphrased from the recorded label text and carries that label as its citation. Nothing is added from outside the labels.
// The text before the first comma of a timing is the short badge the card shows.
const c = (v: string, ...cite: string[]): Cited => ({ v, cite });
const dm = (setid: string) => `https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=${setid}`;
const pi = (key: string, text: string, setid: string): OncSource => ({ key, kind: 'fda-pi', text, url: dm(setid) });

